652	                  : isEditingNoteView
653	                    ? "Close editor"
654	                    : "Close details"
655	              }
656	            >
657	              {isFocusModeView ? "Exit focus" : "Close"}
658	              <kbd className="rounded-[4px] border border-border px-[5px] py-px font-mono text-[10px]/3 text-muted">
659	                esc
660	              </kbd>
661	            </button>
662	          </header>
663	
664	          {isEditingNoteView ? (
665	            <div className="flex min-h-0 flex-auto flex-col overflow-hidden">
666	              <Suspense
667	                fallback={
668	                  <p className={NOTE_BOX} role="status">
669	                    Loading editor…
670	                  </p>
671	                }
672	              >
673	                <RichNoteEditor
674	                  key={`edit-${shownItem.id}`}
675	                  embedded
676	                  body={shownItem.noteBody}
677	                  title={shownItem.title}
678	                  onSave={(body) => actions.onUpdateNote(shownItem, body)}
679	                  onEditingChange={(editing) => {
680	                    setIsEditingNote(editing);
681	                    if (!editing) setIsFocusMode(false);
682	                  }}
683	                  focusMode={isFocusModeView}
684	                  onFocusModeChange={setIsFocusMode}
685	                />
686	              </Suspense>
687	            </div>
688	          ) : (
689	            <>
690	              <Tabs.Panel value="info" tabIndex={-1} className={INSPECTOR_BODY}>
691	                <InfoPanel
692	                  item={shownItem}
693	                  actions={actions}
694	                  memberSpaces={memberSpaces}
695	                  onEditNote={() => {
696	                    setIsFocusMode(false);
697	                    setIsEditingNote(true);
698	                  }}
699	                />
700	              </Tabs.Panel>
701	              <Tabs.Panel value="similar" tabIndex={-1} className={INSPECTOR_BODY}>
702	                <SimilarPanel item={shownItem} similar={similarItems} onOpen={actions.onOpenItem} />
703	              </Tabs.Panel>
704	            </>
705	          )}
