 27	declare global {
 28	  interface HTMLCanvasElement {
 29	    /** HTML-in-Canvas: fires a `paint` event in the next rendering update. */
 30	    requestPaint(): void;
 31	  }
 32	}
 33	
 34	// HTML-in-Canvas paints opaque cross-origin images blank, so remote card images
 35	// load with CORS. The desktop shell (the only app:// page) adds the CORS header
 36	// to image responses; anywhere else most hosts send none and the image would fail.
 37	export function canvasImageCrossOrigin(src: string | undefined) {
 38	  return location.protocol === "app:" && src?.startsWith("https:") ? "anonymous" : undefined;
 39	}
