 41	type LiquidDom = typeof import("@liquid-dom/core");
 42	type LiquidGpu = { lib: LiquidDom; device: GPUDevice; format: GPUTextureFormat };
 43	
 44	let support: Promise<LiquidGpu | null> | undefined;
 45	
 46	// One device for every surface, so pipelines compile once.
 47	function liquidGlassSupport() {
 48	  support ??= (async () => {
 49	    if (!("layoutSubtree" in HTMLCanvasElement.prototype) || !navigator.gpu) return null;
 50	    // Painting support alone is not input support. Keep the live DOM/CSS glass
 51	    // when the experimental canvas would swallow card clicks and context menus.
 52	    if (!canvasAllowsDomInput(document)) return null;
 53	    const adapter = await navigator.gpu.requestAdapter();
 54	    if (!adapter) return null;
 55	    const [device, lib] = await Promise.all([adapter.requestDevice(), import("@liquid-dom/core")]);
 56	    if (!(await canCopyElements(device))) {
 57	      device.destroy();
 58	      return null;
 59	    }
 60	    void device.lost.then(() => {
 61	      support = Promise.resolve(null);
 62	    });
 63	    return { lib, device, format: navigator.gpu.getPreferredCanvasFormat() };
 64	  })().catch(() => null);
 65	  return support;
 66	}
