 68	// The element copy is experimental and has already changed shape once (the
 69	// liquid-dom patch in patches/). Prove it copies a real element before any
 70	// content moves into a canvas, or the library would render blank.
 71	async function canCopyElements(device: GPUDevice) {
 72	  const canvas = document.createElement("canvas");
 73	  canvas.setAttribute("layoutsubtree", "");
 74	  canvas.style.cssText =
 75	    "position:fixed;top:0;left:0;width:1px;height:1px;z-index:-1;pointer-events:none";
 76	  canvas.append(document.createElement("div"));
 77	  const format = navigator.gpu.getPreferredCanvasFormat();
 78	  // The copy requires the canvas to hold a WebGPU context.
 79	  canvas.getContext("webgpu")?.configure({ device, format });
 80	  const texture = device.createTexture({
 81	    size: { width: 1, height: 1 },
 82	    format,
 83	    usage:
 84	      GPUTextureUsage.COPY_DST |
 85	      GPUTextureUsage.TEXTURE_BINDING |
 86	      GPUTextureUsage.RENDER_ATTACHMENT,
 87	  });
 88	  try {
 89	    document.body.append(canvas);
 90	    return await new Promise<boolean>((resolve) => {
 91	      canvas.addEventListener(
 92	        "paint",
 93	        () => {
 94	          try {
 95	            const queue = device.queue as GPUQueue & {
 96	              copyElementImageToTexture(
 97	                source: { source: Element },
 98	                destination: {
 99	                  destination: { texture: GPUTexture };
100	                  width: number;
101	                  height: number;
102	                },
103	              ): void;
104	            };
105	            queue.copyElementImageToTexture(
106	              { source: canvas.firstElementChild as Element },
107	              { destination: { texture }, width: 1, height: 1 },
108	            );
109	            resolve(true);
110	          } catch {
111	            resolve(false);
112	          }
113	        },
114	        { once: true },
115	      );
116	      canvas.requestPaint();
117	      setTimeout(() => resolve(false), 1000);
118	    });
119	  } finally {
120	    canvas.remove();
121	    texture.destroy();
122	  }
123	}
